802→      e.preventDefault();
803→      const input = searchForm.querySelector(".searchTerm").value.trim();
804→      if (!input) return;
805→
806→      const path = "/search/" + encodeURIComponent(input);
807→      loadInPanel(getTargetPanel(), path);
808→    });
809→  }
810→});
